vec3 Idx2Point(int i)
{
    int kNumPoints = 100000;
    float kGoldenFactor = 10.166640738;
    float u = (2.0f / float(kNumPoints-1)) * float(i) - 1.0f;
    float t = kGoldenFactor * float(i);
    float up = sqrt(max(0.0f, 1.0f - u*u));
    return vec3(up*cos(t), up*sin(t), u);
}

vec3 GetGradient(vec3 intPos)
{
    float rand = fract(sin(dot(intPos, vec3(12.9898, 78.233, 1234.5678))) * 43758.5453);
    return Idx2Point(int(rand*100000.0f));
}

float pnoise(float x, float y, float z)
{
    int x0 = int(floor(x));
    int y0 = int(floor(y));
    int z0 = int(floor(z));
    int x1 = int(ceil(x));
    int y1 = int(ceil(y));
    int z1 = int(ceil(z));

    vec3 p = vec3(x,y,z);

    vec3 v[8];
    v[0] = vec3(x0, y0, z0);
    v[1] = vec3(x1, y0, z0);
    v[2] = vec3(x0, y1, z0);
    v[3] = vec3(x1, y1, z0);
    v[4] = vec3(x0, y0, z1);
    v[5] = vec3(x1, y0, z1);
    v[6] = vec3(x0, y1, z1);
    v[7] = vec3(x1, y1, z1);

    vec3 d[8];
    d[0] = p - v[0];
    d[1] = p - v[1];
    d[2] = p - v[2];
    d[3] = p - v[3];
    d[4] = p - v[4];
    d[5] = p - v[5];
    d[6] = p - v[6];
    d[7] = p - v[7];

    float dx = x-float(x0);
    float dy = y-float(y0);
    float dz = z-float(z0);

    float tx = dx * dx * (3.0 - 2.0 * dx);
    float ty = dy * dy * (3.0 - 2.0 * dy);
    float tz = dz * dz * (3.0 - 2.0 * dz);

    float noiseVal = 
        mix(
            mix(
                mix(
                    dot(GetGradient(v[0]), d[0]),
                    dot(GetGradient(v[1]), d[1]),
                    tx),
                mix(
                    dot(GetGradient(v[2]), d[2]),
                    dot(GetGradient(v[3]), d[3]),
                    tx),
                ty
            ),
            mix(
                mix(
                    dot(GetGradient(v[4]), d[4]),
                    dot(GetGradient(v[5]), d[5]),
                    tx),
                mix(
                    dot(GetGradient(v[6]), d[6]),
                    dot(GetGradient(v[7]), d[7]),
                    tx),
                ty
            ),
            tz
        );
    return noiseVal / 0.7; // normalize to about [-1..1];
}

float sqr(float a)
{
    return a*a;
}

float interp(float t)
{
    if(t < 0.5f)
    {
        return 0.0f;
    }
    else if(t < 1.0f)
    {
        t = (t - 0.5f) * 2.0f;
        return -2.0f*t*t*t + 3.0f*t*t;
    }
    else
    {
        return 1.0f;
    }
}


float sample_terrain(float x, float y)
{
    float mountain_region_strength = pnoise(x * 0.001f, 0.0f, 0.0f);
    mountain_region_strength = mountain_region_strength*0.5f + 0.5f;
    mountain_region_strength = interp(mountain_region_strength);

    float ground_height = 200.0;
    ground_height += (pnoise(x * 0.01f, 0.0f, 0.0f)*0.5f+0.5f) * 900.0f * mountain_region_strength;
    ground_height += (pnoise(x * 0.05f, 0.05f, 0.0f)*0.5f+0.5f) * 80.0f * mountain_region_strength;
    ground_height += pnoise(x * 0.02f, y * 0.02f, 0.0f) * 80.0f * mountain_region_strength;
    ground_height += pnoise(x * 0.01f, 0.0f, 0.0f) * 10.0f;

    return y - ground_height;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float noise = sample_terrain(fragCoord.x + iTime * 1000.0f, fragCoord.y);
    vec3 ground_color = vec3(0.1f, 0.8f, 0.1f);
    vec3 air_color = vec3(0.1f, 0.7f, 0.8f);
    fragColor = vec4(noise <= 0.0f ? ground_color : air_color, 1.0f);
}
